import java.nio.file.*;import java.io.*;
public class Main {static void append(Path p,String record)throws IOException{if(record==null||record.isBlank()||record.contains("\n"))throw new IllegalArgumentException("Invalid record");try(BufferedWriter w=Files.newBufferedWriter(p,StandardOpenOption.CREATE,StandardOpenOption.APPEND)){w.write(record);w.newLine();}}public static void main(String[]a)throws Exception{Path p=Path.of("safe-records.txt");append(p,"P1001,192311001,Arun");try{append(p,"bad\nrecord");}catch(IllegalArgumentException e){System.out.println(e.getMessage());}System.out.println(Files.readString(p));}}
